import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"检查点","description":"","frontmatter":{"title":"检查点","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/checkpoint.md","filePath":"cs/checkpoint.md","lastUpdated":1789023840000}'),h={name:"cs/checkpoint.md"};function E(A,a,_,D,m,u){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h1><div class="epigraph"><p>检查点把「REDO 必须从多早的日志开始」往前推；脏页表与活跃事务表写入日志，分析不必从创世读起。</p><footer>—— 据 Mohan et al. ARIES；Gray and Reuter 对检查点的整理</footer></div><p><a href="/cs/aries-recovery">上一课</a>给出分析、REDO、UNDO。本课不重讲 CLR。缺口是日志无限增长：每次崩溃若从最早未刷的更新开始 REDO，重启时间随运行时间线性涨。检查点周期性地记录缓冲与事务快照，截断恢复起点。ACID 作为规格下一课才命名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ARIES 直觉留下「分析出谁脏」。分析从哪个 LSN 开始？模糊检查点：不暂停整个系统刷完所有页，而是记一刀，后台继续刷。恢复从最近完成的检查点开始，用当时的脏页表当 REDO 下限的提示。缺口是<strong>把重启工作量收成周期任务</strong>。</p><p><span class="marginnote">尖锐检查点停世界刷盘，教学简单，生产少用。检查点不等于事务提交，也不是备份。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>开始检查点记录 → 收集脏页与活跃事务 → 结束检查点记录落盘。主恢复指针指向可开始分析的 LSN。日志空间可回收该点之前、且不再被任何活跃事务 UNDO 需要的部分。本课不把厂商的检查点间隔公式当标准。</p>',8)),(e(),n(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CKPT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20DPT%5B%22%E8%84%8F%E9%A1%B5%E8%A1%A8%E5%BF%AB%E7%85%A7%22%5D%0A%20%20CKPT%20--%3E%20ATT%5B%22%E6%B4%BB%E8%B7%83%E4%BA%8B%E5%8A%A1%E8%A1%A8%22%5D%0A%20%20DPT%20--%3E%20REDO%5B%22REDO%20%E8%B5%B7%E7%82%B9%E5%89%8D%E7%A7%BB%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>检查点是恢复性能机制，不改变 steal/no-force 的正确性条件。它与 OS 的[检查点]概念不同：这里对象是数据库日志与缓冲，不是进程映像。后课事务 ACID 的 D（持久）仍以提交记录落盘为准，不是以检查点为准。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入增量备份链当主干。并发调度的正确性规格下一课 ACID。</p><p>后课默认：重启从检查点附近开始。事务要同时满足原子、一致、隔离、持久。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>检查点前移 REDO 起点，缩短分析。</li><li>模糊检查点避免停世界。</li><li>事务规格下一课 ACID。</li><li>出处：ARIES；Gray and Reuter。</li></ul>',7))])}const T=i(h,[["render",E]]);export{f as __pageData,T as default};
